open Port_monad

module type S = sig
  type t

  val record_continuation :
    t -> Continuation.t -> [`Unarized] Flambda_arity.t -> t coq_M

  val record_continuation_use :
    t ->
    Continuation.t ->
    Continuation_use_kind.t ->
    Downwards_env.t ->
    Flambda2_types.t list ->
    (t * Apply_cont_rewrite_id.t) coq_M

  val delete_continuation_uses : t -> Continuation.t -> t coq_M

  val get_typing_env_no_more_than_one_use :
    t -> Continuation.t -> Flambda2_types.Typing_env.t option coq_M

  val num_continuation_uses : t -> Continuation.t -> int coq_M

  val all_continuations_used : t -> Continuation.Set.t coq_M
end
